import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { dirname } from "node:path";

const LIMITS = { title: 300, author: 200, notes: 5000 };

function clamp(value, max) {
  return String(value ?? "").trim().slice(0, max);
}

export function createStore(filePath) {
  let queue = Promise.resolve();
  const withLock = (fn) => {
    const result = queue.then(fn, fn);
    queue = result.then(
      () => {},
      () => {}
    );
    return result;
  };

  async function load() {
    try {
      const data = JSON.parse(await readFile(filePath, "utf8"));
      return Array.isArray(data) ? data : [];
    } catch (err) {
      if (err.code === "ENOENT") return [];
      throw err;
    }
  }

  async function save(books) {
    await mkdir(dirname(filePath), { recursive: true });
    const tmp = `${filePath}.tmp`;
    await writeFile(tmp, JSON.stringify(books, null, 2) + "\n");
    await rename(tmp, filePath);
  }

  return {
    filePath,

    list() {
      return load();
    },

    async get(id) {
      const books = await load();
      return books.find((b) => b.id === id) ?? null;
    },

    add({ title, author = "", notes = "" }) {
      return withLock(async () => {
        const books = await load();
        const book = {
          id: randomUUID(),
          title: clamp(title, LIMITS.title),
          author: clamp(author, LIMITS.author),
          notes: clamp(notes, LIMITS.notes),
          status: "reading",
          createdAt: new Date().toISOString(),
          finishedAt: null,
        };
        books.push(book);
        await save(books);
        return book;
      });
    },

    finish(id) {
      return withLock(async () => {
        const books = await load();
        const book = books.find((b) => b.id === id);
        if (!book) return null;
        if (book.status !== "finished") {
          book.status = "finished";
          book.finishedAt = new Date().toISOString();
          await save(books);
        }
        return book;
      });
    },

    setNotes(id, notes) {
      return withLock(async () => {
        const books = await load();
        const book = books.find((b) => b.id === id);
        if (!book) return null;
        book.notes = clamp(notes, LIMITS.notes);
        await save(books);
        return book;
      });
    },
  };
}

