.notes { white-space: pre-wrap; background: #fff; border: 1px solid #e5e5e5; border-radius: 6px; padding: .75rem; margin: 0 0 1rem; }
.share input { width: 100%; box-sizing: border-box; font: inherit; padding: .45rem; border: 1px solid #ccc; border-radius: 6px; background: #fff; }
a.back { color: #666; font-size: .9rem; }
.empty { color: #777; }
</style>
</head>
<body>
<header><a class="brand" href="/">My Books</a></header>
<main>
${content}
</main>
</body>
</html>
`;
}

function bookItem(book) {
  const finished = book.status === "finished";
  const meta = [
    book.author ? `by ${esc(book.author)}` : "",
    finished && book.finishedAt ? `Finished ${formatDate(book.finishedAt)}` : "",
  ]
    .filter(Boolean)
    .join(" &middot; ");
  return `<li><a href="/books/${esc(book.id)}">${esc(book.title)}</a>${
    meta ? `<p class="meta">${meta}</p>` : ""
  }</li>`;
}

export function homePage({ reading, finished, error }) {
  const list = (books, emptyText) =>
    books.length
      ? `<ul class="books">${books.map(bookItem).join("")}</ul>`
      : `<p class="empty">${emptyText}</p>`;

  return layout(
    "My Books",
    `<h1>My books</h1>
${error ? `<p class="error">${esc(error)}</p>` : ""}
<h2>Currently reading <span class="count">(${reading.length})</span></h2>
${list(reading, "Not reading anything right now.")}
<h2>Finished <span class="count">(${finished.length})</span></h2>
${list(finished, "No finished books yet.")}
<h2>Add a book</h2>
<form class="stack" method="post" action="/books">
<div><label for="title">Title *</label><input id="title" name="title" type="text" required maxlength="300" autofocus></div>
<div><label for="author">Author</label><input id="author" name="author" type="text" maxlength="200"></div>
<div><label for="notes">Notes (optional)</label><textarea id="notes" name="notes" rows="3" maxlength="5000"></textarea></div>
<button type="submit">Add book</button>
</form>`
  );
}

export function bookPage({ book, baseUrl }) {
  const shareUrl = `${baseUrl}/books/${encodeURIComponent(book.id)}`;
  const finished = book.status === "finished";
  const statusLine = finished
    ? `Finished ${formatDate(book.finishedAt)} &middot; Added ${formatDate(book.createdAt)}`
    : `Currently reading &middot; Added ${formatDate(book.createdAt)}`;

  return layout(
    book.title || "Book",
    `<p><a class="back" href="/">&larr; All books</a></p>
<h1>${esc(book.title)}</h1>
<p class="meta">${book.author ? `by ${esc(book.author)}` : "Author unknown"}</p>
<p class="meta">${statusLine}</p>
<h2>Notes</h2>
${
  book.notes
    ? `<div class="notes">${esc(book.notes)}</div>`
    : `<p class="empty">No notes yet.</p>`
}
<form class="stack" method="post" action="/books/${esc(book.id)}/notes">
<label for="notes">Edit notes</label>
<textarea id="notes" name="notes" rows="5" maxlength="5000">${esc(book.notes)}</textarea>
<button type="submit">Save notes</button>
</form>
${
  finished
    ? ""
    : `<form method="post" action="/books/${esc(book.id)}/finish"><button type="submit" class="secondary">Mark as finished</button></form>`
}
<h2>Share</h2>
<p class="meta">Anyone with this link can view this book:</p>
<div class="share"><input readonly value="${esc(shareUrl)}" onclick="this.select()" aria-label="Share link"></div>`
  );
}

export function notFoundPage(message = "That book doesn't exist.") {
  return layout(
    "Not found",
    `<h1>Not found</h1>
<p>${esc(message)}</p>
<p><a href="/">Back to all books</a></p>`
  );
}

