import { createServer } from "node:http";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { createStore } from "./lib/store.js";
import { homePage, bookPage, notFoundPage } from "./lib/views.js";

const MAX_BODY = 64 * 1024;

function readBody(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY) {
        reject(Object.assign(new Error("Payload too large"), { statusCode: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}

function sendHtml(res, status, html) {
  res.writeHead(status, { "content-type": "text/html; charset=utf-8" });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

function baseUrl(req) {
  const host = req.headers.host || "localhost";
  const proto =
    req.headers["x-forwarded-proto"] || (req.socket.encrypted ? "https" : "http");
  return `${proto}://${host}`;
}

async function handle(req, res, store) {
  const url = new URL(req.url, baseUrl(req));
  const pathname = url.pathname.replace(/\/+$/, "") || "/";
  const bookMatch = pathname.match(/^\/books\/([^/]+)$/);
  const actionMatch = pathname.match(/^\/books\/([^/]+)\/(finish|notes)$/);
  const id = (raw) => decodeURIComponent(raw);

  if (req.method === "GET" && pathname === "/") {
    const books = await store.list();
    const reading = books
      .filter((b) => b.status !== "finished")
      .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
    const finished = books
      .filter((b) => b.status === "finished")
      .sort((a, b) => String(b.finishedAt).localeCompare(String(a.finishedAt)));
    const error = url.searchParams.get("error") === "title" ? "A title is required." : null;
    return sendHtml(res, 200, homePage({ reading, finished, error }));
  }

  if (req.method === "POST" && pathname === "/books") {
    const params = new URLSearchParams(await readBody(req));
    const title = (params.get("title") ?? "").trim();
    if (!title) return redirect(res, "/?error=title");
    const book = await store.add({
      title,
      author: params.get("author") ?? "",
      notes: params.get("notes") ?? "",
    });
    return redirect(res, `/books/${encodeURIComponent(book.id)}`);
  }

  if (bookMatch && req.method === "GET") {
    const book = await store.get(id(bookMatch[1]));
    if (!book) return sendHtml(res, 404, notFoundPage());
    return sendHtml(res, 200, bookPage({ book, baseUrl: baseUrl(req) }));
  }

  if (actionMatch && req.method === "POST") {
    const bookId = id(actionMatch[1]);
    const action = actionMatch[2];
    if (action === "finish") {
      const book = await store.finish(bookId);
      if (!book) return sendHtml(res, 404, notFoundPage());
    } else {
      const params = new URLSearchParams(await readBody(req));
      const book = await store.setNotes(bookId, params.get("notes") ?? "");
      if (!book) return sendHtml(res, 404, notFoundPage());
    }
    return redirect(res, pathname.replace(/\/(finish|notes)$/, ""));
  }

  sendHtml(res, 404, notFoundPage("That page doesn't exist."));
}

export function createApp({ dataFile } = {}) {
  const store = createStore(
    dataFile ??
      path.join(path.dirname(fileURLToPath(import.meta.url)), "data", "books.json")
  );
  return createServer((req, res) => {
    handle(req, res, store).catch((err) => {
      const status = err.statusCode ?? 500;
      if (!res.headersSent) {
        sendHtml(
          res,
          status,
          notFoundPage(status === 413 ? "That entry is too large." : "Something went wrong.")
        );
      } else {
        res.end();
      }
    });
  });
}

const isMain =
  process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;

if (isMain) {
  const port = Number(process.env.PORT ?? 3000);
  const app = createApp();
  const store = createStore(app._dataFile);
  app.listen(port, () => {
    console.log(`My Books running at http://localhost:${port} (data: ${store.filePath})`);
  });
}

