import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtemp, rm, readFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { createStore } from "../lib/store.js";

describe("store", () => {
  let dir;
  let file;

  beforeEach(async () => {
    dir = await mkdtemp(path.join(tmpdir(), "books-"));
    file = path.join(dir, "books.json");
  });

  afterEach(async () => {
    await rm(dir, { recursive: true, force: true });
  });

  it("returns an empty list when the file does not exist", async () => {
    const store = createStore(file);
    expect(await store.list()).toEqual([]);
  });

  it("adds a book and reads it back", async () => {
    const store = createStore(file);
    const book = await store.add({ title: "  Dune  ", author: "Frank Herbert", notes: "Spice." });
    expect(book.title).toBe("Dune");
    expect(book.status).toBe("reading");
    expect((await store.get(book.id)).author).toBe("Frank Herbert");
  });

  it("persists across a fresh store instance", async () => {
    const first = createStore(file);
    const book = await first.add({ title: "Dune", author: "Frank Herbert" });
    const second = createStore(file);
    expect((await second.list()).map((b) => b.id)).toEqual([book.id]);
    expect(JSON.parse(await readFile(file, "utf8"))).toHaveLength(1);
  });

  it("marks a book as finished", async () => {
    const store = createStore(file);
    const book = await store.add({ title: "Dune" });
    const done = await store.finish(book.id);
    expect(done.status).toBe("finished");
    expect(done.finishedAt).toBeTruthy();
    expect((await store.get(book.id)).status).toBe("finished");
  });

  it("updates notes", async () => {
    const store = createStore(file);
    const book = await store.add({ title: "Dune", notes: "old" });
    await store.setNotes(book.id, "new notes");
    expect((await store.get(book.id)).notes).toBe("new notes");
  });

  it("returns null for unknown ids", async () => {
    const store = createStore(file);
    expect(await store.get("nope")).toBeNull();
    expect(await store.finish("nope")).toBeNull();
    expect(await store.setNotes("nope", "x")).toBeNull();
  });

  it("generates unique ids", async () => {
    const store = createStore(file);
    const ids = new Set();
    for (let i = 0; i < 20; i++) {
      ids.add((await store.add({ title: `Book ${i}` })).id);
    }
    expect(ids.size).toBe(20);
  });
});

