import { describe, it, expect, beforeAll, afterAll } from "vitest";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { createApp } from "../server.js";

describe("app", () => {
  let dir;
  let server;
  let base;

  beforeAll(async () => {
    dir = await mkdtemp(path.join(tmpdir(), "books-app-"));
    server = createApp({ dataFile: path.join(dir, "books.json") });
    await new Promise((resolve) => server.listen(0, resolve));
    base = `http://localhost:${server.address().port}`;
  });

  afterAll(async () => {
    await new Promise((resolve) => server.close(resolve));
    await rm(dir, { recursive: true, force: true });
  });

  const form = (data) => ({
    method: "POST",
    headers: { "content-type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams(data).toString(),
    redirect: "manual",
  });

  it("serves the home page with both sections", async () => {
    const res = await fetch(`${base}/`);
    const html = await res.text();
    expect(res.status).toBe(200);
    expect(html).toContain("Currently reading");
    expect(html).toContain("Finished");
    expect(html).toContain("Add a book");
  });

  it("rejects a book without a title", async () => {
    const res = await fetch(`${base}/books`, form({ title: "   " }));
    expect(res.status).toBe(303);
    expect(res.headers.get("location")).toBe("/?error=title");
  });

  it("creates a book, shows it, and offers a shareable link", async () => {
    const res = await fetch(
      `${base}/books`,
      form({ title: "Dune", author: "Frank Herbert", notes: "Hook line." })
    );
    expect(res.status).toBe(303);
    const location = res.headers.get("location");

    const page = await fetch(`${base}${location}`);
